create or replace function public.wassafrica_admin_partner_economy() returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare out jsonb; begin if not public.is_platform_admin() then raise exception 'admin_required'; end if; select jsonb_build_object('partners',coalesce((select jsonb_agg(to_jsonb(p) order by p.created_at desc) from public.wassafrica_partners p),'[]'::jsonb),'services',coalesce((select jsonb_agg(to_jsonb(s) order by s.created_at desc) from public.wassafrica_partner_services s),'[]'::jsonb),'rules',coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at desc) from public.wassafrica_partner_commission_rules r),'[]'::jsonb),'referrals',coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at desc) from public.wassafrica_partner_referrals r),'[]'::jsonb),'ledger',coalesce((select jsonb_agg(to_jsonb(l) order by l.created_at desc) from private.wassafrica_partner_commission_ledger l),'[]'::jsonb),'events',coalesce((select jsonb_agg(to_jsonb(e) order by e.occurred_at desc) from private.wassafrica_partner_attribution_events e),'[]'::jsonb)) into out; return out; end $$; revoke all on function public.wassafrica_admin_partner_economy() from public,anon,authenticated; grant execute on function public.wassafrica_admin_partner_economy() to authenticated;
create or replace function public.wassafrica_admin_set_commission_status(p_ledger_id uuid,p_status text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare updated_id uuid; begin if not public.is_platform_admin() then raise exception 'admin_required'; end if; if p_status not in ('pending','confirmed','disputed','cancelled') then raise exception 'invalid_status'; end if; update private.wassafrica_partner_commission_ledger set status=p_status,confirmed_at=case when p_status='confirmed' then coalesce(confirmed_at,now()) else null end where id=p_ledger_id returning id into updated_id; if updated_id is null then raise exception 'ledger_not_found'; end if; return jsonb_build_object('ok',true,'ledger_id',updated_id,'status',p_status); end $$; revoke all on function public.wassafrica_admin_set_commission_status(uuid,text) from public,anon,authenticated; grant execute on function public.wassafrica_admin_set_commission_status(uuid,text) to authenticated;
create or replace function private.wassafrica_record_partner_event(p_referral_id uuid,p_event_type text,p_external_ref text default null,p_amount numeric default null,p_currency text default null,p_payload jsonb default '{}'::jsonb,p_occurred_at timestamptz default now()) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private as $$ declare r record;e_id uuid;rule record;commission numeric:=0;rule_currency text;event_time timestamptz:=coalesce(p_occurred_at,now()); begin if p_event_type not in ('lead','qualified','application','approved','activated','transaction','commission_pending','commission_confirmed','disputed','cancelled','churned') then raise exception 'invalid_event_type'; end if; if p_amount is not null and p_amount<0 then raise exception 'amount_must_be_non_negative'; end if; select r.id,r.partner_id,r.service_id,r.status into r from public.wassafrica_partner_referrals r where r.id=p_referral_id for update; if not found then raise exception 'referral_not_found'; end if; if exists(select 1 from public.wassafrica_partners p where p.id=r.partner_id and p.status not in ('active','approved')) then raise exception 'partner_not_active'; end if; if r.service_id is not null and exists(select 1 from public.wassafrica_partner_services s where s.id=r.service_id and (s.status<>'active' or (s.compliance_required and (s.compliance_validated_at is null or (s.compliance_expires_at is not null and s.compliance_expires_at<event_time))))) then raise exception 'service_not_compliant'; end if; insert into private.wassafrica_partner_attribution_events(referral_id,event_type,external_ref,amount,currency,payload,occurred_at) values(p_referral_id,p_event_type,p_external_ref,p_amount,p_currency,coalesce(p_payload,'{}'::jsonb),event_time) on conflict(referral_id,event_type,external_ref) do nothing returning id into e_id; if e_id is null then select id into e_id from private.wassafrica_partner_attribution_events where referral_id=p_referral_id and event_type=p_event_type and external_ref is not distinct from p_external_ref order by created_at desc limit 1; return jsonb_build_object('ok',true,'duplicate',true,'event_id',e_id); end if; update public.wassafrica_partner_referrals set status=case p_event_type when 'lead' then 'lead' when 'qualified' then 'qualified' when 'application' then 'application' when 'approved' then 'approved' when 'activated' then 'activated' when 'transaction' then 'transaction' when 'commission_pending' then 'commission_pending' when 'commission_confirmed' then 'commission_confirmed' when 'disputed' then 'disputed' when 'cancelled' then 'cancelled' when 'churned' then 'churned' else status end where id=p_referral_id; if p_event_type='transaction' and p_amount is not null then select cr.* into rule from public.wassafrica_partner_commission_rules cr join public.wassafrica_partners p on p.id=cr.partner_id left join public.wassafrica_partner_services s on s.id=cr.service_id where cr.partner_id=r.partner_id and (cr.service_id is null or cr.service_id=r.service_id) and cr.status='active' and p.status='active' and p.compliance_status='approved' and (cr.valid_from is null or cr.valid_from<=event_time::date) and (cr.valid_until is null or cr.valid_until>=event_time::date) and (cr.service_id is null or (s.status='active' and (not s.compliance_required or (s.compliance_validated_at is not null and (s.compliance_expires_at is null or s.compliance_expires_at>=event_time))))) order by (cr.service_id is not null) desc,cr.valid_from desc limit 1; if found then rule_currency:=coalesce(p_currency,rule.currency); commission:=case when rule.model in ('revenue_share','transaction') then p_amount*rule.rate/100 when rule.model='flat' then rule.rate else 0 end; insert into private.wassafrica_partner_commission_ledger(attribution_event_id,referral_id,partner_id,service_id,rule_id,model,basis_amount,rate,commission_amount,currency) values(e_id,p_referral_id,r.partner_id,r.service_id,rule.id,rule.model,p_amount,rule.rate,greatest(commission,0),rule_currency) on conflict(attribution_event_id) do nothing; end if; end if; return jsonb_build_object('ok',true,'duplicate',false,'event_id',e_id,'referral_id',p_referral_id); end $$;